WITH exploded AS (SELECT id, effective_from, currency, EXPLODE_OUTER(tier_prices) AS tier_value FROM price_tiers), valid AS (SELECT *, LENGTH(currency) currency_length, DATEDIFF(CURRENT_DATE(), effective_from) / 365 years_since_effective_from FROM exploded WHERE effective_from >= TO_DATE('2024-02-24') AND effective_from BETWEEN '2024-06-01' AND '2025-10-18'), enriched AS (SELECT id, effective_from, PERCENT_RANK() OVER (PARTITION BY currency ORDER BY years_since_effective_from DESC NULLS LAST) years_since_effective_from_percent_rank FROM valid WHERE effective_from BETWEEN '2023-06-01' AND '2024-03-01'), enriched_price_tiers AS (SELECT id, effective_from, RANK() OVER (ORDER BY years_since_effective_from_percent_rank) years_since_effective_from_percent_rank_rank FROM enriched) SELECT id, effective_from FROM enriched_price_tiers ORDER BY id DESC NULLS LAST, effective_from DESC;
